import random, math
random.seed(0)

def matmul(A,B):
    n=len(A); k=len(B); m=len(B[0])
    return [[sum(A[i][t]*B[t][j] for t in range(k)) for j in range(m)] for i in range(n)]

def transpose(A): return [list(r) for r in zip(*A)]

def gram_schmidt(n, dim):
    # build n random orthogonal-ish vectors -> orthonormal columns of Q (dim x n)
    cols=[[random.gauss(0,1) for _ in range(dim)] for _ in range(n)]
    Q=[]
    for v in cols:
        for q in Q:
            d=sum(a*b for a,b in zip(q,q))
            c=sum(a*b for a,b in zip(v,q))/d
            v=[vi-c*qi for vi,qi in zip(v,q)]
        nn=math.sqrt(sum(x*x for x in v)) or 1.0
        Q.append([x/nn for x in v])
    return [[Q[c][r] for c in range(n)] for r in range(dim)]  # dim x n

def jacobi_eigvals_sym(M, sweeps=60, tol=1e-14):
    n=len(M); A=[row[:] for row in M]
    for _ in range(sweeps):
        off=math.sqrt(sum(A[i][j]**2 for i in range(n) for j in range(n) if i!=j))
        if off<tol: break
        for p in range(n-1):
            for q in range(p+1,n):
                if abs(A[p][q])<1e-18: continue
                theta=(A[q][q]-A[p][p])/(2*A[p][q])
                t=math.copysign(1,theta)/(abs(theta)+math.sqrt(theta*theta+1))
                c=1/math.sqrt(t*t+1); s=t*c
                for k in range(n):
                    Akp=A[k][p]; Akq=A[k][q]
                    A[k][p]=c*Akp-s*Akq; A[k][q]=s*Akp+c*Akq
                for k in range(n):
                    Apk=A[p][k]; Aqk=A[q][k]
                    A[p][k]=c*Apk-s*Aqk; A[q][k]=s*Apk+c*Aqk
        # end sweep
    return sorted((A[i][i] for i in range(n)), reverse=True)

def svd_singular_values(A):
    G=matmul(transpose(A),A)
    ev=jacobi_eigvals_sym(G)
    return [math.sqrt(max(ev_i,0.0)) for ev_i in ev]

def erank_entropy(s):
    tot=sum(s)
    if tot<=0: return 0.0
    H=-sum((x/tot)*math.log(x/tot) for x in s if x>0)
    return math.exp(H)

def prf(s):
    num=sum(x*x for x in s); den=sum(x**4 for x in s)
    return num*num/den if den>0 else 0.0

def hill(s, tailfrac=0.15, kmin=8):
    s=sorted([x for x in s if x>0], reverse=True)
    k=max(kmin, int(tailfrac*len(s)))
    xs=s[:k]
    # Hill: xi = mean( ln(x_i / x_k) )
    xk=xs[-1]
    return sum(math.log(x/xk) for x in xs)/len(xs), k

# ---- TEST 1: recover prescribed spectrum through a real A = U S V^T ----
d=24
sigma_true=[(i+1)**-0.5 for i in range(d)]        # power law a=0.5 -> theoretical Hill = 1/a = 2.0
U=gram_schmidt(d,d); V=gram_schmidt(d,d)
US=[[U[r][c]*sigma_true[c] for c in range(d)] for r in range(d)]
A=matmul(US, transpose(V))
s=svd_singular_values(A)
err=max(abs(a-b)/b for a,b in zip(s,sigma_true))
print("T1 max rel err recovered sigma vs prescribed:", f"{err:.2e}")

# ---- TEST 2: sanity of erank / PRF ----
print("T2 erank(all-equal,16) =", f"{erank_entropy([1.0]*16):.3f}", "(expect 16.0)")
print("T2 erank(rank-1,16)    =", f"{erank_entropy([1.0]+[1e-12]*15):.3f}", "(expect ~1.0)")
print("T2 PRF(all-equal,16)   =", f"{prf([1.0]*16):.3f}", "(expect 16.0)")
print("T2 PRF(rank-1,16)      =", f"{prf([1.0]+[1e-9]*15):.4f}", "(expect ~1.0)")

# ---- TEST 3: Hill exponent recovery on synthetic power-law spectra ----
for a in (0.5,1.0,2.0,4.0):
    sp=[(i+1)**-a for i in range(128)]
    xi,k=hill(sp)
    print(f"T3 a={a}: Hill xi_hat={xi:.3f}  theoretical 1/a={1/a:.3f}  (k={k})")

# ---- TEST 4: uniform spectrum must NOT look heavy-tailed ----
xi_uni,k=hill([random.uniform(0.2,1.0) for _ in range(128)])
xi_pl ,_=hill([ (i+1)**-1.0 for i in range(128)])
print(f"T4 xi(uniform tail)={xi_uni:.3f} (small) vs xi(power-law a=1)={xi_pl:.3f}")
EOF
